import hashlib as _hashlib

def _hash_pw(pw):
    return _hashlib.sha256(pw.encode()).hexdigest()

_TODOS_MODULOS = [
    "📦 Gestión de Datos",
    "📊 Informes",
    "👥 Gestión de Usuarios",
]

def _get_users():
    try:
        df = run_query("SELECT id, username, password_hash, permisos, local FROM app_usuarios ORDER BY username")
        return df
    except:
        return pd.DataFrame(columns=["id","username","password_hash","permisos","local"])

def _ensure_users_table():
    engine = get_engine()
    if engine is None: return
    with engine.connect() as conn:
        conn.execute(text("""
            CREATE TABLE IF NOT EXISTS app_usuarios (
                id SERIAL PRIMARY KEY,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                permisos TEXT DEFAULT ''
            )
        """))
        conn.commit()

# ── Sesiones persistentes ────────────────────────────────────
_SESSION_TIMEOUT_HOURS = 8  # sesión expira tras 8h de inactividad

def _ensure_sessions_table():
    engine = get_engine()
    if engine is None: return
    try:
        with engine.connect() as conn:
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS app_sesiones (
                    token TEXT PRIMARY KEY,
                    username TEXT NOT NULL,
                    role TEXT NOT NULL DEFAULT 'user',
                    permisos TEXT DEFAULT '',
                    last_activity TIMESTAMP NOT NULL DEFAULT NOW()
                )
            """))
            conn.commit()
    except Exception:
        pass

def _create_session(username, role, permisos, local=None):
    """Crea sesión en BD y retorna token."""
    engine = get_engine()
    if engine is None: return None
    token = str(_uuid.uuid4())
    try:
        with engine.connect() as conn:
            conn.execute(text(
                "INSERT INTO app_sesiones (token, username, role, permisos, local, last_activity) "
                "VALUES (:t, :u, :r, :p, :l, NOW())"
            ), {"t": token, "u": username, "r": role, "p": permisos, "l": local})
            conn.commit()
        return token
    except Exception:
        return None

def _validate_session(token):
    """Valida token y actualiza actividad. Retorna (username, role, permisos, local) o None."""
    engine = get_engine()
    if engine is None or not token: return None
    try:
        with engine.connect() as conn:
            df = pd.read_sql(text(
                "SELECT username, role, permisos, local, last_activity FROM app_sesiones WHERE token=:t"
            ), conn, params={"t": token})
            if df.empty: return None
            last = pd.to_datetime(df['last_activity'].iloc[0])
            if (datetime.utcnow() - last).total_seconds() > _SESSION_TIMEOUT_HOURS * 3600:
                conn.execute(text("DELETE FROM app_sesiones WHERE token=:t"), {"t": token})
                conn.commit()
                return None
            conn.execute(text("UPDATE app_sesiones SET last_activity=NOW() WHERE token=:t"), {"t": token})
            conn.commit()
            _local = df['local'].iloc[0] if 'local' in df.columns else None
            return (df['username'].iloc[0], df['role'].iloc[0], df['permisos'].iloc[0], _local)
    except Exception:
        return None

def _destroy_session(token):
    engine = get_engine()
    if engine is None or not token: return
    try:
        with engine.connect() as conn:
            conn.execute(text("DELETE FROM app_sesiones WHERE token=:t"), {"t": token})
            conn.commit()
    except Exception:
        pass

def _cleanup_expired_sessions():
    """Limpia sesiones expiradas (se ejecuta esporádicamente)."""
    engine = get_engine()
    if engine is None: return
    try:
        with engine.connect() as conn:
            conn.execute(text(
                "DELETE FROM app_sesiones WHERE last_activity < NOW() - INTERVAL ':h hours'"
            ).bindparams(h=_SESSION_TIMEOUT_HOURS))
            conn.commit()
    except Exception:
        pass

def _check_login(username, password):
    try:
        engine = get_engine()
        if engine is None:
            return None
        with engine.connect() as conn:
            df = pd.read_sql(
                text("SELECT password_hash, permisos, local FROM app_usuarios WHERE username=:u"),
                conn, params={"u": username}
            )
        if not df.empty and df["password_hash"].iloc[0] == _hash_pw(password):
            _local = df["local"].iloc[0] if "local" in df.columns else None
            _permisos = df["permisos"].iloc[0]
            return (_permisos, _local)
    except Exception:
        pass
    return None

def _get_login_intentos(username):
    """Retorna (intentos, bloqueado_hasta) para el username."""
    try:
        engine = get_engine()
        if engine is None: return (0, None)
        with engine.connect() as conn:
            df = pd.read_sql(
                text("SELECT intentos, bloqueado_hasta FROM login_intentos WHERE username=:u"),
                conn, params={"u": username}
            )
        if df.empty: return (0, None)
        return (int(df['intentos'].iloc[0]), df['bloqueado_hasta'].iloc[0])
    except Exception:
        return (0, None)

def _registrar_intento_fallido(username):
    """Incrementa contador de intentos fallidos. Bloquea 15 min tras 4 intentos."""
    try:
        engine = get_engine()
        if engine is None: return
        intentos_actuales, _ = _get_login_intentos(username)
        nuevos_intentos = intentos_actuales + 1
        bloqueado_hasta = None
        if nuevos_intentos >= 4:
            bloqueado_hasta = "NOW() + INTERVAL '15 minutes'"
        with engine.connect() as conn:
            if intentos_actuales == 0:
                conn.execute(text(
                    "INSERT INTO login_intentos (username, intentos, bloqueado_hasta, ultimo_intento) "
                    "VALUES (:u, :i, " + (bloqueado_hasta if bloqueado_hasta else "NULL") + ", NOW()) "
                    "ON CONFLICT (username) DO UPDATE SET intentos=:i, "
                    "bloqueado_hasta=" + (bloqueado_hasta if bloqueado_hasta else "NULL") + ", ultimo_intento=NOW()"
                ), {"u": username, "i": nuevos_intentos})
            else:
                conn.execute(text(
                    "UPDATE login_intentos SET intentos=:i, "
                    "bloqueado_hasta=" + (bloqueado_hasta if bloqueado_hasta else "NULL") + ", "
                    "ultimo_intento=NOW() WHERE username=:u"
                ), {"u": username, "i": nuevos_intentos})
            conn.commit()
    except Exception:
        pass

def _resetear_intentos(username):
    """Resetea contador tras login exitoso."""
    try:
        engine = get_engine()
        if engine is None: return
        with engine.connect() as conn:
            conn.execute(text(
                "UPDATE login_intentos SET intentos=0, bloqueado_hasta=NULL WHERE username=:u"
            ), {"u": username})
            conn.commit()
    except Exception:
        pass

def _esta_bloqueado(username):
    """Retorna (bloqueado: bool, segundos_restantes: int)."""
    try:
        engine = get_engine()
        if engine is None: return (False, 0)
        with engine.connect() as conn:
            df = pd.read_sql(
                text("SELECT bloqueado_hasta, NOW() as ahora FROM login_intentos WHERE username=:u"),
                conn, params={"u": username}
            )
        if df.empty or df['bloqueado_hasta'].iloc[0] is None:
            return (False, 0)
        bloqueado_hasta = pd.to_datetime(df['bloqueado_hasta'].iloc[0])
        ahora = pd.to_datetime(df['ahora'].iloc[0])
        if bloqueado_hasta > ahora:
            segundos = int((bloqueado_hasta - ahora).total_seconds())
            return (True, segundos)
        return (False, 0)
    except Exception:
        return (False, 0)

def _render_login():
    st.markdown("""
    <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;
                min-height:60vh;gap:0.5rem">
        <div style="font-family:'DM Serif Display',serif;font-size:2.5rem;color:#d4a853;
                    letter-spacing:-0.02em;margin-bottom:1rem">🍽️ MRP Gastro</div>
        <div style="font-size:0.8rem;color:#666;text-transform:uppercase;letter-spacing:0.1em;
                    margin-bottom:2rem">Sistema de Costeos</div>
    </div>
    """, unsafe_allow_html=True)
    col = st.columns([1,2,1])[1]
    with col:
        st.markdown("#### Iniciar Sesión")
        username = st.text_input("Usuario", key="login_user")
        password = st.text_input("Contraseña", type="password", key="login_pw")
        if st.button("Ingresar", use_container_width=True, type="primary"):
            if not username.strip():
                st.error("Ingresa tu usuario.")
            else:
                bloqueado, segundos = _esta_bloqueado(username.strip())
                if bloqueado:
                    minutos = segundos // 60
                    segs    = segundos % 60
                    st.error(f"🔒 Usuario bloqueado por demasiados intentos fallidos. Intenta en {minutos}m {segs}s.")
                else:
                    result = _check_login(username.strip(), password)
                    if result is not None:
                        _resetear_intentos(username.strip())
                        permisos_raw, user_local = result
                        role    = "admin" if permisos_raw == "admin" else "user"
                        permisos = permisos_raw
                        token   = _create_session(username.strip(), role, permisos, local=user_local)
                        if token:
                            st.query_params["s"] = token
                        st.session_state["logged_in"]     = True
                        st.session_state["current_user"]  = username.strip()
                        st.session_state["user_role"]     = role
                        st.session_state["user_permisos"] = permisos
                        st.session_state["user_local"]    = user_local
                        st.session_state["session_token"] = token
                        st.rerun()
                    else:
                        _registrar_intento_fallido(username.strip())
                        _, segundos_post = _esta_bloqueado(username.strip())
                        intentos, _ = _get_login_intentos(username.strip())
                        restantes = max(0, 4 - intentos)
                        if segundos_post > 0:
                            st.error("🔒 Demasiados intentos fallidos. Usuario bloqueado por 15 minutos.")
                        else:
                            st.error(f"Usuario o contraseña incorrectos. {restantes} intento(s) restante(s) antes del bloqueo.")

def _user_puede(modulo_key):
    """Verifica si el usuario actual tiene permiso para el módulo."""
    if st.session_state.get("user_role") == "admin":
        return True
    permisos = st.session_state.get("user_permisos", "")
    return modulo_key in permisos

def _render_gestion_usuarios():
    st.markdown("""
    <div style="margin-bottom:1.5rem">
        <div style="font-size:0.72rem;text-transform:uppercase;letter-spacing:0.12em;color:#555;margin-bottom:4px">Admin</div>
        <div style="font-family:'DM Serif Display',serif;font-size:2rem;color:#f0ede8;letter-spacing:-0.02em">
            👥 Gestión de Usuarios
        </div>
    </div>""", unsafe_allow_html=True)

    _ensure_users_table()
    gu_tab1, gu_tab2 = st.tabs(["👤 Usuarios", "➕ Crear Usuario"])

    with gu_tab1:
        df_users = _get_users()
        if df_users.empty:
            st.info("No hay usuarios registrados.")
        else:
            for _, row in df_users.iterrows():
                with st.expander(f"👤 {row['username']} {('· ' + str(row.get('local','')) ) if row.get('local') else ''}"):
                    permisos_act = row['permisos'] if row['permisos'] else ""
                    opciones_mod = ["📦 Gestión de Datos", "📊 Informes", "📋 Notas de Crédito"]
                    sel = st.multiselect(
                        "Módulos habilitados",
                        opciones_mod,
                        default=[m for m in opciones_mod if m in permisos_act],
                        key=f"perm_{row['username']}"
                    )
                    nuevos_permisos = ",".join(sel)

                    # Local assignment
                    _locales_adm = run_query("SELECT DISTINCT local FROM compras WHERE local IS NOT NULL ORDER BY local")
                    _locales_adm_list = ["— Sin restricción —"] + (_locales_adm['local'].tolist() if not _locales_adm.empty else [])
                    _local_actual = str(row.get('local') or '')
                    _local_idx = _locales_adm_list.index(_local_actual) if _local_actual in _locales_adm_list else 0
                    nuevo_local = st.selectbox("Local asignado", _locales_adm_list,
                                               index=_local_idx, key=f"loc_{row['username']}")
                    nuevo_local_val = None if nuevo_local == "— Sin restricción —" else nuevo_local

                    col_a, col_b, col_c = st.columns(3)
                    with col_a:
                        nueva_pw = st.text_input("Nueva contraseña (opcional)", type="password",
                                                  key=f"pw_{row['username']}", placeholder="Dejar vacío = sin cambio")
                    with col_b:
                        if st.button("💾 Guardar", key=f"save_{row['username']}"):
                            try:
                                engine = get_engine()
                                with engine.connect() as conn:
                                    if nueva_pw.strip():
                                        conn.execute(text(
                                            "UPDATE app_usuarios SET permisos=:p, password_hash=:h, local=:l WHERE username=:u"),
                                            {"p": nuevos_permisos, "h": _hash_pw(nueva_pw), "l": nuevo_local_val, "u": row["username"]})
                                    else:
                                        conn.execute(text(
                                            "UPDATE app_usuarios SET permisos=:p, local=:l WHERE username=:u"),
                                            {"p": nuevos_permisos, "l": nuevo_local_val, "u": row["username"]})
                                    conn.commit()
                                st.success("✅ Guardado")
                            except Exception as e:
                                st.error(f"Error: {e}")
                    with col_c:
                        if st.button("🗑️ Eliminar", key=f"del_{row['username']}"):
                            try:
                                engine = get_engine()
                                with engine.connect() as conn:
                                    conn.execute(text("DELETE FROM app_usuarios WHERE username=:u"),
                                                 {"u": row["username"]})
                                    conn.commit()
                                st.success("Eliminado")
                                st.rerun()
                            except Exception as e:
                                st.error(f"Error: {e}")

    with gu_tab2:
        st.markdown("#### Nuevo Usuario")
        nu_user = st.text_input("Usuario", key="nu_user")
        nu_pw   = st.text_input("Contraseña", type="password", key="nu_pw")
        opciones_mod2 = ["📦 Gestión de Datos", "📊 Informes", "📋 Notas de Crédito"]
        nu_perm = st.multiselect("Módulos habilitados", opciones_mod2, key="nu_perm")
        _locales_nu = run_query("SELECT DISTINCT local FROM compras WHERE local IS NOT NULL ORDER BY local")
        _locales_nu_list = ["— Sin restricción —"] + (_locales_nu['local'].tolist() if not _locales_nu.empty else [])
        nu_local = st.selectbox("Local asignado", _locales_nu_list, key="nu_local")
        nu_local_val = None if nu_local == "— Sin restricción —" else nu_local
        if st.button("➕ Crear Usuario", key="btn_crear_user"):
            if not nu_user.strip() or not nu_pw.strip():
                st.warning("Completa usuario y contraseña.")
            else:
                try:
                    engine = get_engine()
                    with engine.connect() as conn:
                        conn.execute(text(
                            "INSERT INTO app_usuarios (username, password_hash, permisos, local) VALUES (:u,:h,:p,:l)"),
                            {"u": nu_user.strip(), "h": _hash_pw(nu_pw), "p": ",".join(nu_perm), "l": nu_local_val})
                        conn.commit()
                    st.success(f"✅ Usuario {nu_user} creado.")
                    st.rerun()
                except Exception as e:
                    st.error(f"Error: {e}")



