# BASE DE DATOS
# ============================================================
@st.cache_resource
def get_engine():
    try:
        db = st.secrets["connections"]["supabase"]
        conn_str = (
            f"postgresql+psycopg2://{db['user']}:{db['password']}"
            f"@{db['host']}:{db['port']}/{db['database']}?sslmode=require"
        )
        return create_engine(
            conn_str,
            pool_pre_ping=True,
            pool_recycle=180,
            pool_timeout=10,
            pool_size=2,          # máximo 2 conexiones persistentes
            max_overflow=3,       # hasta 5 conexiones totales en pico
            connect_args={
                "options":              "-c statement_timeout=30000",
                "connect_timeout":      8,
                "keepalives":           1,
                "keepalives_idle":      30,
                "keepalives_interval":  10,
                "keepalives_count":     3,
            }
        )
    except Exception as e:
        st.error(f"❌ Error de conexión: {e}")
        return None


def run_query(sql, params=None):
    engine = get_engine()
    if engine is None:
        return pd.DataFrame()
    try:
        with engine.connect() as conn:
            return pd.read_sql(text(sql), conn, params=params or {})
    except Exception as e:
        st.error(f"Error en consulta: {e}")
        return pd.DataFrame()


def init_exclusiones():
    """Crea las tablas compras_excluidas y sku_colacion si no existen."""
    engine = get_engine()
    if engine is None:
        return
    try:
        with engine.connect() as conn:
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS compras_excluidas (
                    id         SERIAL PRIMARY KEY,
                    compra_id  INTEGER NOT NULL UNIQUE,
                    sku        TEXT,
                    motivo     TEXT DEFAULT 'compra_emergencia',
                    creado_en  TIMESTAMP DEFAULT NOW()
                )
            """))
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS sku_colacion (
                    id        SERIAL PRIMARY KEY,
                    sku       TEXT NOT NULL UNIQUE,
                    nombre    TEXT,
                    creado_en TIMESTAMP DEFAULT NOW()
                )
            """))
            conn.commit()
    except Exception:
        pass


# ============================================================
# LÓGICA MRP (código 1 preservado íntegramente)
# ============================================================
def process_bom(df_v, df_d, df_p):
    df_v.columns = df_v.columns.str.strip()
    df_d.columns = df_d.columns.str.strip()
    df_p.columns = df_p.columns.str.strip()

    df_v = df_v.rename(columns={'SKU': 'SKU_VENTA', 'Cantidad': 'CANT_VENTA'})
    skus_vendidos = set(df_v['SKU_VENTA'].astype(str).str.strip().str.upper())

    def validar_opcion(row):
        es_op = str(row['EsOpcion']).strip()
        if pd.isna(row['EsOpcion']) or es_op in ["", "0", "4"]:
            return True
        return str(row['SKU']).strip().upper() in skus_vendidos

    df_d_ready = df_d[df_d.apply(validar_opcion, axis=1)].copy()
    m1 = pd.merge(df_v, df_d_ready, left_on='SKU_VENTA', right_on='CODIGO VENTA', how='inner')

    es_proc = m1['SKU'].str.startswith('PRO-', na=False)
    df_insumos_directos = m1[~es_proc].copy()
    df_procesados_a_explotar = m1[es_proc].copy()

    if not df_procesados_a_explotar.empty:
        rendimientos = df_p.groupby('Codigo Venta')['CantReceta'].sum().reset_index()
        rendimientos = rendimientos.rename(columns={'CantReceta': 'TOTAL_RECETA_AUTO'})

        df_p_clean = df_p.rename(columns={
            'Codigo Venta': 'COD_P',
            'Ingrediente': 'NOM_P',
            'CantEfic': 'CE_P',
            'CantReceta': 'CR_P',
            'Porcion': 'MARK_P',
            'UM Salida': 'UM_P',
            'SKU Ingrediente': 'SKU_P'
        })
        df_p_final = pd.merge(df_p_clean, rendimientos, left_on='COD_P', right_on='Codigo Venta', how='left')
        m2 = pd.merge(df_procesados_a_explotar, df_p_final, left_on='SKU', right_on='COD_P', how='left')

        def calcular_m2(row):
            if row['MARK_P'] == 1:
                return row['CANT_VENTA'] * row['CantReal'] * row['CE_P']
            else:
                divisor = row['TOTAL_RECETA_AUTO'] if row['TOTAL_RECETA_AUTO'] > 0 else 1
                return row['CANT_VENTA'] * row['CantReal'] * (row['CE_P'] / divisor)

        m2['CANT_OUT'] = m2.apply(calcular_m2, axis=1)
        exp_f = m2[['SKU_P', 'NOM_P', 'CANT_OUT', 'UM_P']].rename(
            columns={'SKU_P': 'SKU_FIN', 'NOM_P': 'ING_FIN', 'UM_P': 'UM_FIN'})
    else:
        exp_f = pd.DataFrame()

    df_insumos_directos['CANT_OUT'] = (
        df_insumos_directos['CANT_VENTA'] * df_insumos_directos['CantReal']
    )
    dir_out = df_insumos_directos[['SKU', 'Ingrediente', 'CANT_OUT', 'UM']].rename(
        columns={'SKU': 'SKU_FIN', 'Ingrediente': 'ING_FIN', 'UM': 'UM_FIN'})

    consolidado = pd.concat([dir_out, exp_f], ignore_index=True)
    resumen = consolidado.groupby(['SKU_FIN', 'UM_FIN'], as_index=False).agg(
        {'CANT_OUT': 'sum', 'ING_FIN': 'first'})

    def formatear(row):
        um = str(row['UM_FIN']).upper()
        if um in ['G', 'ML', 'CC']:
            return row['CANT_OUT'] / 1000
        return row['CANT_OUT']

    resumen['TOTAL'] = resumen.apply(formatear, axis=1)
    return resumen[['SKU_FIN', 'ING_FIN', 'UM_FIN', 'TOTAL']].rename(
        columns={'SKU_FIN': 'SKU', 'ING_FIN': 'Insumo', 'UM_FIN': 'UM', 'TOTAL': 'Total Kg/L/Un'})


# ============================================================
# CÁLCULO DE COSTO TEÓRICO POR PLATO (Informe 1)
# Directos: CantReal × MUC
# Procesados: CantEfic × MUC  (usando último precio por SKU)
# ============================================================
@st.cache_data(ttl=300, show_spinner=False)
def calcular_costo_platos(fecha_i, fecha_f, local):
    """
    Costo teórico por plato usando MUC correcto:
      MUC = costo_realfinal / (cant_conv * formato)   → ya está en $/unidad_base_del_SKU

    Para ingredientes directos:
      costo = cant_real × MUC        (cant_real en la misma unidad que el SKU: g, un, etc.)

    Para procesados (PRO-):
      El SKU es un sub-plato. Su costo se calcula recursivamente desde su propia receta
      en la tabla recetas (es_procesado=True, codigo_venta = SKU_PRO).
      Se usa cant_efic (cantidad eficiente del procesado) × costo_unitario_procesado.

    NO se aplica factor_um: el MUC ya está expresado en la unidad base del SKU
    ($/g para carnes/verduras, $/un para panes, etc.), que coincide con cant_real/cant_efic.
    """
    # MUC ponderado del período — promedio ponderado por gasto.
    # Fallback al último precio histórico (global) si no hay compras en el período para ese local.
    _filtro_local_precio = f"AND UPPER(local) = UPPER('{local}')" if local != "Todos" else ""

    precio_sql = f"""
        SELECT sku, precio_unitario FROM (
            -- Precio ponderado del período (directo, por local)
            SELECT sku,
                   SUM(costo_realfinal) / NULLIF(SUM(cant_conv * NULLIF(formato,0)), 0) AS precio_unitario,
                   1 AS prioridad
            FROM compras
            WHERE cant_conv > 0 AND costo_realfinal > 0 AND formato > 0
              AND fecha_dte::date BETWEEN '{fecha_i}' AND '{fecha_f}'
              AND sku IN (SELECT DISTINCT sku_ingrediente FROM recetas WHERE sku_ingrediente IS NOT NULL)
              {_filtro_local_precio}
            GROUP BY sku

            UNION ALL

            -- Precio ponderado del período (via equivalencia, por local)
            SELECT e.sku_receta AS sku,
                   SUM(c.costo_realfinal) / NULLIF(SUM(c.cant_conv * NULLIF(c.formato,0)), 0) AS precio_unitario,
                   2 AS prioridad
            FROM compras c
            JOIN sku_equivalencias e ON c.sku = e.sku_compra
            WHERE c.cant_conv > 0 AND c.costo_realfinal > 0 AND c.formato > 0
              AND c.fecha_dte::date BETWEEN '{fecha_i}' AND '{fecha_f}'
              AND e.sku_receta IN (SELECT DISTINCT sku_ingrediente FROM recetas WHERE sku_ingrediente IS NOT NULL)
              {_filtro_local_precio.replace('local', 'c.local')}
            GROUP BY e.sku_receta

            UNION ALL

            -- Fallback: último precio histórico (directo, global)
            SELECT sku, precio_unitario, 3 AS prioridad FROM (
                SELECT DISTINCT ON (sku) sku,
                       costo_realfinal / NULLIF(cant_conv * NULLIF(formato,0), 0) AS precio_unitario
                FROM compras
                WHERE cant_conv > 0 AND costo_realfinal > 0 AND formato > 0
                  AND sku IN (SELECT DISTINCT sku_ingrediente FROM recetas WHERE sku_ingrediente IS NOT NULL)
                ORDER BY sku, fecha_dte DESC
            ) fb1

            UNION ALL

            -- Fallback: último precio histórico (via equivalencia, global)
            SELECT sku, precio_unitario, 4 AS prioridad FROM (
                SELECT DISTINCT ON (e.sku_receta) e.sku_receta AS sku,
                       c.costo_realfinal / NULLIF(c.cant_conv * NULLIF(c.formato,0), 0) AS precio_unitario
                FROM compras c
                JOIN sku_equivalencias e ON c.sku = e.sku_compra
                WHERE c.cant_conv > 0 AND c.costo_realfinal > 0 AND c.formato > 0
                  AND e.sku_receta IN (SELECT DISTINCT sku_ingrediente FROM recetas WHERE sku_ingrediente IS NOT NULL)
                ORDER BY e.sku_receta, c.fecha_dte DESC
            ) fb2
        ) combined
        WHERE precio_unitario IS NOT NULL AND precio_unitario > 0
        ORDER BY sku, prioridad
    """
    df_precio_raw = run_query(precio_sql)
    # Keep only first (lowest prioridad) price per SKU
    df_precio = df_precio_raw.drop_duplicates(subset='sku', keep='first').reset_index(drop=True) if not df_precio_raw.empty else pd.DataFrame()

    if df_precio.empty:
        return pd.DataFrame()

    df_rec = get_recetas()
    if df_rec.empty:
        return pd.DataFrame()

    _es_op  = pd.to_numeric(df_rec["es_opcion"], errors="coerce")
    # df_dir  = recipes for sale plates (everything else), excluding pure options
    df_proc = df_rec[df_rec['codigo_venta'].astype(str).str.startswith('PRO-')].copy()
    df_dir  = df_rec[
        ~df_rec['codigo_venta'].astype(str).str.startswith('PRO-') &
        (_es_op.isna() | (_es_op == 0) | (_es_op == 6))
    ].copy()
    # Los PRO- tienen sus propios ingredientes directos en la tabla recetas
    # con es_procesado=True. Usamos cant_efic × MUC para cada ingrediente del PRO-.
    proc_ingredientes = df_proc.copy()
    proc_ingredientes['cant_efic'] = pd.to_numeric(proc_ingredientes['cant_efic'], errors='coerce').fillna(0)
    proc_ingredientes = pd.merge(
        proc_ingredientes, df_precio, left_on='sku_ingrediente', right_on='sku', how='left'
    )
    proc_ingredientes['precio_unitario'] = pd.to_numeric(
        proc_ingredientes['precio_unitario'], errors='coerce'
    ).fillna(0)
    proc_ingredientes['costo_parcial'] = proc_ingredientes['cant_efic'] * proc_ingredientes['precio_unitario']

    # Costo total del lote por PRO-
    costo_lote = proc_ingredientes.groupby('codigo_venta')['costo_parcial'].sum().reset_index()
    costo_lote.columns = ['codigo_venta', 'costo_lote']

    # Tamaño del lote = SUM(cant_real) cuando porcion=0, o 1 cuando porcion=1
    porcion_por_pro = df_proc.groupby('codigo_venta')['porcion'].first().reset_index()
    cant_lote = proc_ingredientes.groupby('codigo_venta')['cant_real'].sum().reset_index()
    cant_lote.columns = ['codigo_venta', 'cant_lote']

    costo_pro_df = pd.merge(costo_lote, porcion_por_pro, on='codigo_venta', how='left')
    costo_pro_df = pd.merge(costo_pro_df, cant_lote, on='codigo_venta', how='left')
    costo_pro_df['porcion'] = pd.to_numeric(costo_pro_df['porcion'], errors='coerce').fillna(0)
    costo_pro_df['cant_lote'] = pd.to_numeric(costo_pro_df['cant_lote'], errors='coerce').fillna(1)

    # Si porcion=1: costo unitario = costo_lote (ya es por unidad)
    # Si porcion=0: costo unitario por g/ml = costo_lote / cant_lote
    costo_pro_df['costo_unitario_pro'] = costo_pro_df.apply(
        lambda r: r['costo_lote'] if r['porcion'] == 1 else r['costo_lote'] / max(r['cant_lote'], 1),
        axis=1
    )

    costo_pro = costo_pro_df[['codigo_venta', 'costo_unitario_pro']].copy()
    costo_pro.columns = ['sku_ingrediente_pro', 'costo_unitario_pro']

    # ── DIRECTOS: ingredientes simples del plato de venta ────────────────────
    df_dir['cant_real'] = pd.to_numeric(df_dir['cant_real'], errors='coerce').fillna(0)

    # Separar directos que son ingredientes de compra vs los que son PRO-
    es_pro = df_dir['sku_ingrediente'].astype(str).str.startswith('PRO-')
    dir_compra = df_dir[~es_pro].copy()
    dir_pro    = df_dir[es_pro].copy()

    # Directos de compra: cant_real × MUC
    dir_compra = pd.merge(dir_compra, df_precio, left_on='sku_ingrediente', right_on='sku', how='left')
    dir_compra['precio_unitario'] = pd.to_numeric(dir_compra['precio_unitario'], errors='coerce').fillna(0)
    dir_compra['costo_parcial']   = dir_compra['cant_real'] * dir_compra['precio_unitario']

    # es_opcion=6: flavor options — weighted average cost using actual MODX sales distribution
    _es_op_dir = pd.to_numeric(dir_compra['es_opcion'], errors='coerce')
    dir_op6    = dir_compra[_es_op_dir == 6].copy()
    dir_normal = dir_compra[_es_op_dir != 6].copy()

    if not dir_op6.empty:
        # Get MODX sales distribution for the period
        _filtro_local_w = f"AND UPPER(local) = UPPER('{local}')" if local != "Todos" else ""
        _q_modx = f"""
            SELECT sku_producto, SUM(cantidad_vendida) AS ventas
            FROM ventas
            WHERE fecha_venta BETWEEN '{fecha_i}' AND '{fecha_f}'
              AND es_opcion = true
              AND ba_opcion IN ('BA.140','BA.230','BA.240')
              {_filtro_local_w}
            GROUP BY sku_producto
        """
        df_modx = run_query(_q_modx)

        if not df_modx.empty:
            _total_modx = df_modx['ventas'].sum()
            df_modx['peso'] = df_modx['ventas'] / _total_modx if _total_modx > 0 else 1 / len(df_modx)

            # Map MODX sku → ingredient sku
            _modx_map = {
                'MODX-013': 'AL-PO-001',
                'MODX-014': 'AL-PO-014',
                'MODX-015': 'AL-PO-012',
                'MODX-016': 'AL-PO-013',
            }
            df_modx['sku_ingrediente'] = df_modx['sku_producto'].map(_modx_map)
            df_modx = df_modx.dropna(subset=['sku_ingrediente'])

            # Merge weights into dir_op6
            dir_op6 = pd.merge(dir_op6, df_modx[['sku_ingrediente','peso']],
                               on='sku_ingrediente', how='left')
            dir_op6['peso'] = dir_op6['peso'].fillna(0)

            # Weighted cost per plate = SUM(costo_parcial × peso)
            dir_op6['costo_ponderado'] = dir_op6['costo_parcial'] * dir_op6['peso']
            dir_op6_avg = dir_op6.groupby('codigo_venta')['costo_ponderado'].sum().reset_index()
            dir_op6_avg.columns = ['codigo_venta', 'costo_parcial']
        else:
            # Fallback: simple average if no MODX sales data
            dir_op6_avg = dir_op6.groupby('codigo_venta')['costo_parcial'].mean().reset_index()
            dir_op6_avg.columns = ['codigo_venta', 'costo_parcial']

        dir_compra = pd.concat([dir_normal[['codigo_venta','costo_parcial']],
                                dir_op6_avg], ignore_index=True)
    else:
        dir_compra = dir_normal[['codigo_venta','costo_parcial']]

    # Directos PRO-: cant_real × costo_unitario_pro (calculado arriba)
    dir_pro = pd.merge(
        dir_pro, costo_pro,
        left_on='sku_ingrediente', right_on='sku_ingrediente_pro', how='left'
    )
    dir_pro['costo_unitario_pro'] = pd.to_numeric(dir_pro['costo_unitario_pro'], errors='coerce').fillna(0)
    dir_pro['costo_parcial']      = dir_pro['cant_real'] * dir_pro['costo_unitario_pro']

    # Consolidar todo
    costo_total = pd.concat(
        [dir_compra if isinstance(dir_compra, pd.DataFrame) and 'costo_parcial' in dir_compra.columns
         else dir_compra[['codigo_venta','costo_parcial']],
         dir_pro[['codigo_venta','costo_parcial']]],
        ignore_index=True
    )
    costo_platos = costo_total.groupby('codigo_venta')['costo_parcial'].sum().reset_index()
    costo_platos.columns = ['sku_producto', 'cmv_base']
    return costo_platos


@st.cache_data(ttl=300, show_spinner=False)
def calcular_cmv_con_opciones(fecha_i, fecha_f, local):
    """
    CMV unitario por plato = costo_base + cmv_opciones_unitario

    cmv_opciones_unitario = SUM(cant_opcion_i × costo_receta_opcion_i) / cant_padre_total

    cant_padre se obtiene en query separada para evitar inflación por el JOIN con opciones.
    """
    filtro_local = "AND UPPER(local) = UPPER(:l)" if local != "Todos" else ""
    params_loc = {'i': str(fecha_i), 'f': str(fecha_f)}
    if local != "Todos": params_loc['l'] = local

    costo_base = calcular_costo_platos(fecha_i, fecha_f, local)
    if costo_base.empty:
        return pd.DataFrame()

    # ── Cantidad total vendida de cada plato padre (query independiente) ──────
    q_cant_padre = f"""
        SELECT sku_producto, SUM(cantidad_vendida) AS cant_padre
        FROM ventas
        WHERE fecha_venta BETWEEN :i AND :f
          AND es_opcion = false
          {filtro_local}
        GROUP BY sku_producto
    """
    df_cant_padre = run_query(q_cant_padre, params_loc)
    if df_cant_padre.empty:
        result = costo_base.copy()
        result['cmv_opciones'] = 0.0
        result['cmv_unitario'] = result['cmv_base']
        return result[['sku_producto', 'cmv_unitario', 'cmv_base', 'cmv_opciones']]

    df_cant_padre['cant_padre'] = pd.to_numeric(df_cant_padre['cant_padre'], errors='coerce').fillna(1)

    # ── Opciones costeables: SOLO Pan y Proteína ─────────────────────────────
    # La clave es agrupar por (id_orden, ab_categoria, sku_padre, sku_opcion).
    # Dentro de cada pedido, ab_categoria identifica a qué plato base
    # pertenecen las opciones. Si hay 2 sandwiches distintos en el mismo pedido
    # con distinto ab_categoria, sus opciones no se mezclan.
    # Si hay 2 unidades del MISMO plato (mismo sku_padre), la cantidad de
    # opciones se divide por la cantidad del padre en ese pedido.
    ba_costeables_sql = "', '".join(BA_COSTEABLES)
    filtro_v = filtro_local

    _plates_2_scoops_sql = 'POS-002'
    _plates_3_scoops_sql = 'POS-008'

    q_opciones = f"""
        WITH padres AS (
            SELECT id_orden, ab_categoria, sku_producto AS sku_padre,
                   SUM(cantidad_vendida) AS cant_padre,
                   CASE
                       WHEN sku_producto = '{_plates_3_scoops_sql}' THEN 3
                       WHEN sku_producto = '{_plates_2_scoops_sql}' THEN 2
                       ELSE 1
                   END AS scoops_por_unidad
            FROM ventas
            WHERE fecha_venta BETWEEN :i AND :f
              AND es_opcion = false
              AND ab_categoria IS NOT NULL
              {filtro_v}
            GROUP BY id_orden, ab_categoria, sku_producto
        ),
        total_por_ab_orden AS (
            SELECT id_orden, ab_categoria, SUM(cant_padre) AS total_padres
            FROM padres
            GROUP BY id_orden, ab_categoria
        ),
        opciones_raw AS (
            SELECT id_orden, ab_categoria, sku_producto AS sku_opcion,
                   SUM(cantidad_vendida) AS cant_opcion
            FROM ventas
            WHERE fecha_venta BETWEEN :i AND :f
              AND es_opcion = true
              AND ba_opcion IN ('{ba_costeables_sql}')
              {filtro_v}
            GROUP BY id_orden, ab_categoria, sku_producto
        ),
        -- Cap total options per (order, ab_categoria) to expected scoops
        opciones_cap AS (
            SELECT
                o.id_orden,
                o.ab_categoria,
                o.sku_opcion,
                o.cant_opcion,
                SUM(o.cant_opcion) OVER (PARTITION BY o.id_orden, o.ab_categoria) AS total_opciones,
                SUM(p.cant_padre * p.scoops_por_unidad) AS total_esperado
            FROM opciones_raw o
            JOIN (
                SELECT id_orden, ab_categoria,
                       SUM(cant_padre * scoops_por_unidad) AS cant_padre,
                       SUM(cant_padre * scoops_por_unidad) AS scoops_por_unidad
                FROM padres
                GROUP BY id_orden, ab_categoria
            ) p ON p.id_orden = o.id_orden AND p.ab_categoria = o.ab_categoria
            GROUP BY o.id_orden, o.ab_categoria, o.sku_opcion, o.cant_opcion
        ),
        opciones AS (
            SELECT
                id_orden, ab_categoria, sku_opcion,
                -- Scale down cant_opcion if total options exceed expected scoops
                CASE
                    WHEN total_opciones > total_esperado AND total_opciones > 0
                    THEN cant_opcion * total_esperado::float / total_opciones::float
                    ELSE cant_opcion
                END AS cant_opcion
            FROM opciones_cap
        )
        SELECT
            p.sku_padre,
            o.sku_opcion,
            SUM(o.cant_opcion::float * p.cant_padre::float / NULLIF(t.total_padres, 0)) AS cant_opcion_total
        FROM padres p
        JOIN total_por_ab_orden t ON t.id_orden = p.id_orden AND t.ab_categoria = p.ab_categoria
        JOIN opciones o            ON o.id_orden = p.id_orden AND o.ab_categoria = p.ab_categoria
        GROUP BY p.sku_padre, o.sku_opcion
    """
    df_op = run_query(q_opciones, params_loc)

    if df_op.empty:
        result = costo_base.copy()
        result['cmv_opciones'] = 0.0
        result['cmv_unitario'] = result['cmv_base']
        return result[['sku_producto', 'cmv_unitario', 'cmv_base', 'cmv_opciones']]

    df_op['cant_opcion_total'] = pd.to_numeric(df_op['cant_opcion_total'], errors='coerce').fillna(0)

    # ── Costo unitario de cada SKU opción desde recetas (es_opcion != 0) ──────
    # Costo de cada SKU opción — usar costo_base que ya tiene el costo correcto
    # de todos los platos incluyendo CHUX-021, PANX-001, etc.
    costo_op_sku = costo_base.copy().rename(columns={
        'sku_producto':  'sku_opcion',
        'cmv_base':      'costo_receta_opcion'
    })

    # cant_opcion_norm ya viene normalizada por unidades del padre en cada pedido.
    # Multiplicamos por costo unitario y sumamos por padre → cmv_opciones total acumulado.
    # Dividimos por cant_padre (total vendido) → cmv_opciones unitario.
    df_op = pd.merge(df_op, costo_op_sku, on='sku_opcion', how='left')
    df_op['costo_receta_opcion'] = pd.to_numeric(df_op['costo_receta_opcion'], errors='coerce').fillna(0)
    df_op['costo_opcion_acum'] = df_op['cant_opcion_total'] * df_op['costo_receta_opcion']

    agg = df_op.groupby('sku_padre')['costo_opcion_acum'].sum().reset_index()
    agg.columns = ['sku_producto', 'costo_opciones_acum']

    # cant_padre total del período (ya calculado arriba)
    agg = pd.merge(agg, df_cant_padre, on='sku_producto', how='left')
    agg['cant_padre'] = agg['cant_padre'].fillna(1)
    # cant_opcion_norm ya fue dividida por cant_padre_orden en el SQL,
    # así que costo_opciones_acum / cant_padre_total da el costo unitario correcto.
    agg['cmv_opciones'] = agg['costo_opciones_acum'] / agg['cant_padre'].clip(lower=1)

    result = pd.merge(costo_base, agg[['sku_producto', 'cmv_opciones']], on='sku_producto', how='left')
    result['cmv_opciones'] = result['cmv_opciones'].fillna(0)
    result['cmv_unitario'] = result['cmv_base'] + result['cmv_opciones']
    return result[['sku_producto', 'cmv_unitario', 'cmv_base', 'cmv_opciones']]





# ============================================================
# COSTO PERÍODO: MUC ponderado del período, fallback última compra
# ============================================================

# ============================================================
# INFORME 1: RENTABILIDAD POR PRODUCTO / CATEGORÍA
# ============================================================
@st.cache_data(ttl=300, show_spinner=False)
def informe_rentabilidad(fecha_i, fecha_f, local):
    engine = get_engine()
    if engine is None:
        return pd.DataFrame()

    filtro_local_r = "AND UPPER(local) = UPPER(:l)" if local != "Todos" else ""
    params = {"i": str(fecha_i), "f": str(fecha_f)}
    if local != "Todos":
        params["l"] = local

    q_v = f"""
        SELECT sku_producto,
               MAX(nombre_producto)  as nombre_producto,
               MAX(categoria_menu)   as categoria_menu,
               MAX(ab_categoria)     as ab_categoria,
               SUM(cantidad_vendida) as cant,
               SUM(monto_venta_real) as venta
        FROM ventas
        WHERE fecha_venta BETWEEN :i AND :f
          AND es_opcion = false
          AND sku_producto NOT LIKE 'CP%'
          AND sku_producto NOT LIKE 'MEJ%'
          {filtro_local_r}
        GROUP BY sku_producto
    """
    df_v = run_query(q_v, params)
    if df_v.empty:
        st.warning("No hay ventas para el período/local seleccionado.")
        return pd.DataFrame()

    df_v['cant']  = pd.to_numeric(df_v['cant'],  errors='coerce').fillna(0)
    df_v['venta'] = pd.to_numeric(df_v['venta'], errors='coerce').fillna(0)

    # CMV con opciones ponderadas (nuevo método)
    df_cmv = calcular_cmv_con_opciones(fecha_i, fecha_f, local)

    df = pd.merge(df_v, df_cmv, on='sku_producto', how='left')
    df['cmv_unitario'] = pd.to_numeric(df.get('cmv_unitario'), errors='coerce').fillna(0)
    df['cmv_base']     = pd.to_numeric(df.get('cmv_base'),     errors='coerce').fillna(0)
    df['cmv_opciones'] = pd.to_numeric(df.get('cmv_opciones'), errors='coerce').fillna(0)

    # Indicadores por producto
    df['cmv_total']    = df['cant'] * df['cmv_unitario']
    df['cmv_pct']      = df.apply(lambda r: r['cmv_total']/r['venta']*100 if r['venta']>0 else 0, axis=1)
    df['mc_unitario']  = df['venta']/df['cant'].clip(lower=1) - df['cmv_unitario']
    df['mc_total']     = df['venta'] - df['cmv_total']
    df['margen_pct']   = df.apply(lambda r: r['mc_total']/r['venta']*100 if r['venta']>0 else 0, axis=1)

    # Popularidad por categoría
    total_cant_cat = df.groupby('categoria_menu')['cant'].transform('sum')
    n_items_cat    = df.groupby('categoria_menu')['sku_producto'].transform('count')
    df['mix_pct']      = df['cant'] / total_cant_cat.clip(lower=1) * 100
    df['umbral_pct']   = 100 / n_items_cat * 70  # 70% del reparto uniforme

    # Cuadrante BCG gastronómico por categoría
    # Usamos MEDIANA de mix_pct y mc_unitario por categoría como umbral
    # Esto evita que outliers distorsionen la clasificación
    mediana_mix_cat = df.groupby('categoria_menu')['mix_pct'].transform('median')
    mediana_mc_cat  = df.groupby('categoria_menu')['mc_unitario'].transform('median')
    def cuadrante(r):
        alta_pop  = r['mix_pct']      >= mediana_mix_cat[r.name]
        alto_mc   = r['mc_unitario']  >= mediana_mc_cat[r.name]
        if alta_pop and alto_mc:   return "⭐ Estrella"
        if not alta_pop and alto_mc: return "❓ Interrogante"
        if alta_pop and not alto_mc: return "🐄 Vaca"
        return "🐶 Perro"
    df['cuadrante'] = df.apply(cuadrante, axis=1)

    # Compatibilidad con código existente
    df['costo_unitario_teorico'] = df['cmv_unitario']
    df['costo_unitario_periodo'] = df['cmv_unitario']
    df['costo_total_teorico']    = df['cmv_total']
    df['costo_total_periodo']    = df['cmv_total']
    df['rentabilidad_teorica']   = df['mc_total']
    df['rentabilidad_periodo']   = df['mc_total']
    df['margen_teorico']         = df['margen_pct']
    df['margen_periodo']         = df['margen_pct']
    df['costo_total']            = df['cmv_total']
    df['rentabilidad']           = df['mc_total']

    return df.sort_values('venta', ascending=False)



