                                    f'<td style="padding:7px 10px;text-align:right;color:#aaa">{_dr["comprado"]:,.2f}</td>'
                                    f'<td style="padding:7px 10px;text-align:right;color:#aaa">{_dr["real_ut"]:,.2f}</td>'
